    "explanation": "Căn cứ: `Incoterm - ebook - bản Tiếng Việt.pdf` / Lời giới thiệu (Mục 6 - Một số điểm khác biệt chính giữa Incoterms 2020 so với bản 2010) [1] và Quy tắc FCA (Mục 5 - Vận đơn với dấu On-board trong mua bán FCA [2, 3]; Điều khoản A6/B6 - Chứng từ giao hàng/vận tải [4, 5]). - + **Bản chất học thuật**: Trong giao dịch sử dụng điều kiện FCA, người bán hoàn thành nghĩa vụ giao hàng khi giao cho người chuyên chở tại địa điểm chỉ định (thường là trước khi hàng được xếp lên tàu biển), do đó người chuyên chở thông thường chỉ phát hành chứng từ nhận hàng để chở (Received for shipment B/L) [2, 6]. Tuy nhiên, nếu thanh toán bằng thư tín dụng (L/C), ngân hàng mở L/C lại đòi hỏi vận đơn đã xếp hàng lên tàu (On-board Bill of Lading) có xác nhận hàng đã nằm yên vị trên tàu [2]. + **Cơ chế mới của Incoterms® 2020**: Nhằm giải quyết vướng mắc thực tiễn này, Incoterms® 2020 bổ sung quy định cho phép các bên thỏa thuận trong hợp đồng một cơ chế hỗ trợ [1, 2]: người mua sẽ chỉ thị/yêu cầu người chuyên chở do mình thuê phát hành cho người bán một vận đơn có xác nhận hàng đã xếp lên tàu (On-board B/L) sau khi hàng hóa được xếp lên tàu [2, 3, 5]. + **Trích dẫn chuẩn xác**: Tài liệu `Incoterm - ebook - bản Tiếng Việt.pdf` nêu rõ: *\"Để giải quyết các trường hợp mà sử dụng điều kiện FCA nhưng người bán vẫn cần 1 vận đơn có dấu On-board thì ở Incoterms 2020, điều kiện FCA đã quy định thêm việc người chuyên chở có thể được người mua hàng chỉ định để phát hành vận đơn có dấu On-board cho người bán. Nếu hai bên cùng đồng ý thỏa thuận trong hợp đồng về việc này, người mua sẽ phải chỉ định người chuyên chở của mình phát hành 1 vận đơn có dấu On-board cho người bán\"* [2, 3]. Đồng thời tại mục B6 (FCA) quy định: *\"Nếu các bên đã thỏa thuận, người mua phải chịu rủi ro và chi phí để chỉ định người chuyên chở phát hành cho người bán một chứng từ vận tải chứng minh rằng hàng hóa đã được xếp lên tàu (ví dụ như là vận đơn có dấu On-board)\"* [5].",
