    "explanation": "Căn cứ: 'Incoterm - ebook - bản Tiếng Việt.pdf' / Phần \"Các điều kiện sử dụng cho một hoặc nhiều phương thức vận tải\" / Quy tắc DPU (Delivered at Place Unloaded) - Mục 2 \"Chuyển giao hàng hóa và rủi ro\", Mục A2 \"Giao hàng\" và Mục A7 \"Thông quan xuất khẩu/nhập khẩu\". - + **Bản chất của DPU:** Theo Incoterms® 2020, DPU (Delivered at Place Unloaded) quy định người bán chỉ hoàn thành nghĩa vụ giao hàng khi hàng hóa đã được **dỡ xuống** khỏi phương tiện vận tải chở tới và đặt dưới sự định đoạt của người mua tại địa điểm đến chỉ định [1, 2]. DPU là quy tắc duy nhất yêu cầu người bán phải thực hiện và chịu mọi rủi ro, chi phí liên quan đến việc dỡ hàng tại nơi đến [1, 3]. + **Vấn đề quan trọng nhất:** Nếu kho của người mua không có thiết bị phù hợp để dỡ hàng, người bán sẽ gặp khó khăn hoặc không thể hoàn thành nghĩa vụ dỡ hàng theo đúng quy tắc. Hướng dẫn sử dụng DPU trong tài liệu nêu rõ: *\"DPU là điều kiện duy nhất mà yêu cầu người bán dỡ hàng xuống tại nơi đến. Người bán nên chắc chắn rằng mình có đủ khả năng để có thể tổ chức việc dỡ hàng tại nơi đến, hoặc nếu không thì nên cân nhắc sử dụng điều kiện DAP.\"* [1] + **Phân tích các đáp án còn lại:** * **B sai:** Theo Mục A7(a) điều kiện DPU, người bán có nghĩa vụ thông quan xuất khẩu, không phải người mua [4]. * **C sai:** DPU thuộc nhóm các quy tắc áp dụng cho mọi phương thức vận tải (vận tải đa phương thức), không chỉ riêng đường biển [5]. * **D sai:** Theo Mục A4 điều kiện DPU, người bán bắt buộc phải ký hợp đồng vận tải để chở hàng hóa tới nơi đến quy định (kho của người mua) [6].",
