    "explanation": "Căn cứ: - *Giáo trình giao dịch ngoại thương.pdf*: Chương II - Mục 2.1.1 (EXW - Giao tại xưởng), Mục 2.1.4 (CIP - Cước phí và phí bảo hiểm trả tới) và Chương IV - Mục 3.2 (Cơ cấu giá hàng xuất khẩu) [5-8]. - - Bản chất học thuật: - Giá **EXW (Ex Works)** là giá giao tại xưởng, đại diện cho nghĩa vụ và phạm vi chi phí tối thiểu của người bán [6, 10]. Người bán chỉ cần đặt hàng hóa sẵn sàng dưới quyền định đoạt của người mua tại cơ sở của mình mà không chịu chi phí bốc hàng, thông quan xuất khẩu hay vận chuyển [5, 9, 13]. - Giá **CIP (Carriage and Insurance Paid To)** là giá cước phí và phí bảo hiểm trả tới nơi đến quy định (Paris) [7, 11]. Khi chuyển sang CIP, người bán phải gánh thêm các chi phí mà ở EXW mình không phải chịu, bao gồm: chi phí thông quan xuất khẩu, cước phí vận tải chặng chính đưa hàng tới Paris, và phí mua bảo hiểm hàng hóa [7, 11, 12, 14]. - Trích dẫn chuẩn xác: - *Giáo trình giao dịch ngoại thương.pdf*: *\"Trong 11 quy tắc Incoterms® 2010, EXW thể hiện nghĩa vụ tối thiểu cho người bán\"* [6], còn CIP *\"có nghĩa người bán giao hàng cho người chuyên chở... và người bán phải ký hợp đồng và trả mọi chi phí vận chuyển cần thiết để đưa hàng hóa tới nơi đến quy định. Người bán còn phải ký hợp đồng bảo hiểm để bảo hiểm những rủi ro...\"* [7]. - *Incoterm - ebook - bản Tiếng Việt.pdf*: *\"EXW là điều kiện Incoterms mà nghĩa vụ của người bán là ít nhất\"* [10], trong khi CIP đòi hỏi *\"người bán phải ký hợp đồng và trả chi phí vận tải cần thiết để đưa hàng hóa đến địa điểm được chỉ định. Ngoài ra người bán sẽ phải mua bảo hiểm cho hàng hóa\"* [11]. - Như vậy, người bán bắt buộc phải tính toán lại và cộng thêm các chi phí vận tải, bảo hiểm và thông quan xuất khẩu vào đơn giá EXW ban đầu (100.000 USD) để lập giá chào CIP Paris [7, 8, 11].",
