    "explanation": "Căn cứ: + *Giáo trình giao dịch ngoại thương* (PGS.TS Phạm Duy Liên): Chương II - Incoterms, Mục 2.2.3 \"CFR - Tiền hàng và cước phí\" [12, 13] và Mục 4.g \"Không bổ sung thuật ngữ vào Incoterms\" / \"Qui định về nghĩa vụ mua bảo hiểm cho hàng hóa\" [14-16]. - + **Mối quan hệ giữa Incoterms và Hợp đồng mua bán**: Incoterms là bộ quy tắc tập quán thương mại quy định các nghĩa vụ tối thiểu/cơ bản và không thay thế toàn bộ hợp đồng [17, 18]. Các bên hoàn toàn có quyền thỏa thuận bổ sung các nghĩa vụ riêng (như việc người bán CFR tự nguyện hoặc thỏa thuận mua thêm bảo hiểm cho lô hàng) trong hợp đồng mua bán mà không bắt buộc phải làm thay đổi tên gọi hay bản chất pháp lý của điều kiện cơ sở giao hàng CFR đã chọn, miễn là điều khoản bổ sung được ghi rõ [15, 16]. + **Phân tích loại trừ các đáp án sai**: * *B sai*: Trong CFR, nghĩa vụ thông quan nhập khẩu và nộp thuế nhập khẩu thuộc về người mua (tiểu mục B7), người bán chỉ làm thủ tục thông quan xuất khẩu (tiểu mục A7) [13, 21, 22]. * *C sai*: Theo quy tắc CFR, rủi ro chuyển sang cho người mua ngay khi hàng hóa được giao an toàn trên tàu tại cảng bốc hàng (nước xuất khẩu), rủi ro không tự động chuyển hay kéo dài tới cảng đích [12, 20, 23]. * *D sai*: Quy tắc CFR và CIF là hai điều kiện thương mại độc lập trong hệ thống Incoterms [24, 25]. Việc người bán CFR tự nguyện mua thêm bảo hiểm theo thỏa thuận riêng không làm điều kiện CFR \"tự động\" biến thành CIF, vì CIF đòi hỏi quy định bắt buộc về nghĩa vụ bảo hiểm A5 của người bán theo chuẩn Incoterms [26-28].",
