    "answer": "B",
    "explanation": "Căn cứ: - *Giáo trình giao dịch ngoại thương.pdf*: Chương II - Mục 1.3.2 (Phân loại theo quyền vận tải và nơi giao hàng) [9], Mục 2.2.4 (Quy tắc CIF) [8, 10] và Mục 4.f (\"Hợp đồng theo nhóm C là 'hợp đồng gửi hàng'\") [11]. - Nhận định của người mua là **sai về bản chất học thuật của Incoterms**. Các quy tắc thuộc Nhóm C (bao gồm CIF - Cost, Insurance and Freight) có đặc trưng cơ bản là có **hai điểm tới hạn khác nhau** (hai mốc tách biệt về rủi ro và chi phí) [10, 14]: 1. *Mốc chuyển giao rủi ro:* Rủi ro về mất mát hoặc hư hỏng hàng hóa được chuyển từ người bán sang người mua ngay khi hàng hóa được đặt an toàn trên con tàu chuyên chở **tại cảng bốc hàng (cảng đi)** [8, 13]. 2. *Mốc phân chia chi phí:* Người bán chịu chi phí cước vận tải biển và phí bảo hiểm đưa hàng **đến cảng đích quy định** [8, 13]. Do đó, các hợp đồng Nhóm C (như CIF) bản chất là **\"hợp đồng gửi hàng\" (shipment contract)** chứ không phải \"hợp đồng hàng đến\" (arrival contract - Nhóm D) [11]. Địa điểm ghi kèm theo CIF (cảng đích) chỉ là mốc phân chia chi phí, **không bao giờ là địa điểm chuyển giao rủi ro** [12]. Mọi rủi ro phát sinh trong quá trình vận chuyển trên biển từ cảng bốc đến cảng đích đều do người mua chịu [8, 11].",
