    "explanation": "Căn cứ: + *Incoterm - ebook - bản Tiếng Việt.pdf*: Lời giới thiệu – Mục 6 \"Một số điểm khác biệt chính giữa Incoterms 2020 so với bản 2010\"; Điều kiện FCA (Free Carrier) – Mục \"Hướng dẫn sử dụng\" (điểm 5: \"Vận đơn với dấu On-board trong mua bán FCA\") và Mục A6/B6. - + Theo tập quán thương mại, quy tắc FCA áp dụng cho mọi phương thức vận tải. Người bán hoàn thành nghĩa vụ giao hàng khi giao hàng cho người chuyên chở do người mua chỉ định tại cơ sở người bán hoặc tại một điểm tập kết (như CFS, CY) trước khi hàng được xếp lên tàu biển. + Khi thanh toán bằng phương thức Tín dụng thư (L/C), các ngân hàng thường bắt buộc người xuất khẩu phải xuất trình Vận đơn đường biển có xác nhận hàng đã xếp lên tàu (*On-board Bill of Lading*) thì mới giải ngân thanh toán. Điều này gây khó khăn lớn cho người bán theo FCA vì họ đã hoàn thành giao hàng từ trước khi hàng lên tàu và người chuyên chở không có nghĩa vụ cấp vận đơn *On-board* cho người bán. + Để khắc phục bất cập này, Incoterms® 2020 đã bổ sung tùy chọn tại điều kiện FCA (Mục A6/B6): Nếu các bên thỏa thuận trong hợp đồng, người mua phải chỉ định người chuyên chở của mình phát hành cho người bán một vận đơn có ghi chú đã xếp hàng lên tàu (*On-board notation*) sau khi hàng đã bốc lên tàu. + Mục đích cốt lõi của quy định mới này là hỗ trợ người bán có được chứng từ vận tải *On-board* phù hợp nhằm đáp ứng các điều kiện thanh toán nghiêm ngặt của ngân hàng khi áp dụng L/C. + *Các đáp án còn lại sai vì:* (A) FCA vẫn là quy tắc áp dụng cho mọi phương thức vận tải; (C) Nghĩa vụ thuê phương tiện vận tải chính vẫn thuộc về người mua; (D) Mốc chuyển giao rủi ro của FCA vẫn giữ nguyên tại thời điểm giao hàng cho người chuyên chở, không bị dời sang lúc xếp xong hàng lên tàu.",
