    "explanation": "Căn cứ: - *Giáo trình giao dịch ngoại thương* (PGS.TS. Phạm Duy Liên - NXB Đại học Quốc gia / ĐH Ngoại thương), **Chương III: Hợp đồng trong giao dịch thương mại quốc tế**, Mục 2.1.7 *\"Điều khoản thanh toán\"*, tiểu mục 2.1.7.2 *\"Thời hạn thanh toán\"* (trang 116). - - **Bản chất học thuật**: Theo *Giáo trình giao dịch ngoại thương* (Mục 2.1.7.2, trang 116), thanh toán trả trước (Advance Payment / Prepayment) là việc người mua thanh toán tiền hàng trước khi người bán tiến hành giao hàng. Về mặt bản chất kinh tế, đây là hình thức người mua cấp tín dụng cho người bán. Phương thức này đẩy toàn bộ rủi ro thanh toán và rủi ro thực hiện hợp đồng về phía người mua, đồng thời bảo vệ tuyệt đối lợi ích tài chính cho người bán. - **Lý giải đáp án đúng (B)**: Người bán thường đề xuất và bắt buộc áp dụng điều khoản trả trước trong các trường hợp: 1. **Hàng hóa đặc thù / Sản xuất theo đơn đặt hàng riêng**: Hàng được gia công, chế tạo theo tiêu chuẩn, quy cách kỹ thuật riêng biệt của người mua (Mục 2.1.17 & 4.2.2.3). Nếu người mua hủy đơn hoặc không nhận hàng, người bán sẽ rất khó hoặc không thể tiêu thụ lô hàng đó cho bên thứ ba. 2. **Đối tác mới, thiếu lịch sử tín dụng**: Khi người bán chưa kiểm tra được uy tín, năng lực tài chính hay lịch sử tín dụng của đối tác (Mục 5.1.1, trang 178). 3. **Rủi ro quốc gia/thị trường cao**: Thị trường nước người mua bất ổn về chính trị, kinh tế hoặc có kiểm soát ngoại hối ngặt nghèo. - **Phân tích loại trừ các phương án sai**: - **A sai**: Khi người mua nắm thế chủ động đàm phán (thị trường thuộc về bên mua), người mua sẽ yêu cầu các điều kiện thanh toán có lợi cho mình như trả sau (Deferred Payment), ghi sổ (Open Account) hoặc L/C trả chậm, chứ không chấp nhận trả trước. - **C sai**: Khi hai bên là đối tác lâu năm, tin tưởng tuyệt đối và muốn tối giản hóa thủ tục chứng từ ngân hàng, họ thường chọn phương thức chuyển tiền sau (T/T after delivery) hoặc ghi sổ (Open Account). - **D sai**: Trong giao dịch thương mại quốc tế, điều khoản thanh toán tuân theo nguyên tắc tự do thỏa thuận giữa các bên, không có quy định pháp lý nào bắt buộc giao hàng bằng đường biển phải dùng thanh toán trả trước.",
