    "explanation": "Căn cứ: Giáo trình giao dịch ngoại thương* (PGS.TS Phạm Duy Liên) / Chương I: Tổng quan về giao dịch thương mại quốc tế / Mục 3.2 (Chào bán hàng - Offer) [1] và Mục 3.5 (Chấp nhận - Acceptance) [2]; Chương III: Hợp đồng trong giao dịch thương mại quốc tế / Mục 1.1 (Các khái niệm có liên quan) [3]. - - **Bản chất pháp lý của việc gửi hợp đồng dự thảo**: Việc Công ty A (bên bán) soạn thảo, ký tên, đóng dấu và gửi bản mềm hợp đồng (PDF) qua email cho Công ty B thể hiện ý chí muốn bán hàng theo các điều kiện xác định, về mặt pháp lý đây chính là một **Chào bán hàng (Offer) / Đề nghị giao kết hợp đồng** [1]. - **Chấp nhận đề nghị giao kết hợp đồng bằng hành vi**: Theo nguyên tắc giao kết hợp đồng trong thương mại quốc tế (Công ước Viên 1980 - CISG), Luật Thương mại và Bộ luật Dân sự Việt Nam, **Chấp nhận (Acceptance)** là sự đồng ý hoàn toàn với đề nghị giao kết hợp đồng [2]. Sự chấp nhận này không bắt buộc phải thể hiện bằng văn bản có chữ ký trực tiếp, mà có thể được xác lập thông qua **hành vi thực hiện hợp đồng** (hành vi cụ thể) [2]. - **Thời điểm hợp đồng phát sinh hiệu lực**: Việc Công ty B căn cứ vào thông tin tài khoản trên bản hợp đồng dự thảo để chuyển khoản 20.000 USD tiền đặt cọc cho Công ty A được pháp luật công nhận là hành vi thực hiện chấp nhận đề nghị giao kết hợp đồng [2, 4]. Ngay khi hành vi chấp nhận này được thực hiện và Công ty A nhận được tiền cọc, hợp đồng thương mại quốc tế đã chính thức **được thành lập và phát sinh hiệu lực pháp lý ràng buộc cả hai bên** [2]. - Do đó, lập luận của Công ty B cho rằng hợp đồng chưa có hiệu lực vì chưa đặt bút ký là **SAI**. Công ty B không thể lấy lý do này để đơn phương hủy hợp đồng và đòi lại 100% tiền đặt cọc [2].",
