    "explanation": "Căn cứ: Giáo trình giao dịch ngoại thương.pdf* / Chương III: Hợp đồng trong giao dịch thương mại quốc tế / Mục 2.3. Hợp đồng gia công (Mục 2.3.3. Điều khoản về định mức tiêu hao nguyên vật liệu) [1]. - - **Về mặt pháp lý và quản lý hải quan**: Định mức tiêu hao nguyên vật liệu là tỷ lệ nguyên vật liệu tính trên một đơn vị sản phẩm [1]. Đây là chỉ tiêu cốt lõi để cơ quan Hải quan quản lý việc thực hiện chế độ ưu đãi thuế quan (miễn thuế nhập khẩu nguyên liệu gia công xuất khẩu), xác định nghĩa vụ thuế cũng như kiểm soát gian lận thương mại [1]. - **Trách nhiệm đối với bên đặt gia công (Công ty B)**: Định mức thỏa thuận trong hợp đồng (1,05 kg thép/sản phẩm) đã bao gồm tỷ lệ hao hụt cho phép (5%). Việc phát sinh chi phí tiêu hao thực tế lên 1,12 kg thép/sản phẩm (vượt 0,07 kg/sản phẩm) do tay nghề công nhân yếu và sự cố kỹ thuật máy móc hoàn toàn thuộc về lỗi vận hành và rủi ro sản xuất của bên nhận gia công (Công ty A). Do đó, Công ty A phải tự chịu chi phí đền bù lượng nguyên liệu thiếu hụt này cho Công ty B; Công ty B không có nghĩa vụ phải cung cấp bổ sung miễn phí (*bác bỏ phương án A*). - **Trách nhiệm đối với cơ quan Hải quan**: Doanh nghiệp nhận gia công phải đăng ký và tuân thủ định mức tiêu hao đã cam kết với cơ quan Hải quan [1]. Khi lượng tiêu hao vượt định mức do lỗi nội bộ của bên nhận gia công, Công ty A không có quyền tự động điều chỉnh tăng định mức (*bác bỏ phương án B*), và cơ quan Hải quan cũng không tự động miễn thuế cho phần vượt định mức này (*bác bỏ phương án C*). Công ty A bắt buộc phải kê khai nộp thuế nhập khẩu cho phần nguyên liệu tiêu hao vượt định mức (0,07 kg thép/sản phẩm) và chịu phạt vi phạm hành chính (nếu có) theo quy định của pháp luật về quản lý hải quan.",
