    "answer": "B",
    "explanation": "Căn cứ: 'Giáo trình giao dịch ngoại thương.pdf' (PGS.TS Phạm Duy Liên) / Chương III: Hợp đồng trong giao dịch thương mại quốc tế / Mục 2.2: Hợp đồng trao đổi hàng hóa (Mục 2.2.5 \"Điều khoản thanh toán\" & Mục 2.2.6 \"Điều khoản đảm bảo thực hiện hợp đồng\") và Chương I / Mục 4.2.2.1: Mua bán đối lưu [1-3]. - 1. **Bản chất của giao dịch trao đổi hàng hóa (buôn bán đối lưu):** Hàng hóa trao đổi mang tính chất bù trừ trị giá tương đương [1]. Trong điều khoản thanh toán, hai bên quy định một ngân hàng đứng ra làm nhiệm vụ mở tài khoản bù trừ giá trị giao dịch giữa hai bên [1, 3]. 2. **Các biện pháp đảm bảo thực hiện hợp đồng:** Để khống chế lẫn nhau và ngăn ngừa vi phạm, hợp đồng trao đổi hàng hóa cho phép áp dụng các biện pháp đảm bảo như sử dụng tài khoản đặc biệt tại ngân hàng, L/C đối ứng, hoặc **\"phạt khi giao hàng thiếu hoặc chậm giao hàng\"** (phạt bằng ngoại tệ mạnh) [2, 3]. 3. **Xử lý tài chính trong tình huống thực tế:** - Công ty A đã hoàn tất 100% nghĩa vụ giao nông sản đúng thời hạn, còn Công ty B giao thiếu 10% số lượng máy và giao chậm 20 ngày [3]. - Ngân hàng bù trừ sẽ tiến hành **ghi nhận bù trừ giá trị tương đương giữa 100% nông sản của A và 90% số máy thực giao của B** [1, 3]. - Đối với phần nghĩa vụ vi phạm của B (giao thiếu 10% số máy và giao chậm 20 ngày), ngân hàng và hai bên sẽ căn cứ vào điều khoản phạt đã thỏa thuận trong hợp đồng để **tính khoản tiền phạt và buộc B phải thanh toán khoản tiền chênh lệch trị giá cùng tiền phạt cho A** [2, 3]. 4. **Loại trừ các phương án sai:** - **A sai:** Hợp đồng trao đổi hàng hóa hoàn toàn cho phép quy định điều khoản phạt bằng tiền/ngoại tệ mạnh và ngân hàng có căn cứ hợp đồng để tính toán, xử lý [2, 3]. - **C sai:** Ngân hàng không có quyền tự ý hủy bỏ toàn bộ hợp đồng khi một bên đã giao đủ và bên kia đã giao phần lớn hàng hóa; xử lý tài chính qua bù trừ và tiền phạt là giải pháp chuẩn mực [3]. - **D sai:** Ngân hàng bù trừ dựa trên giá trị hàng hóa thực giao từng đợt/đến hạn, không bắt buộc bên đã giao đủ phải chờ đợi vô thời hạn mới được tiến hành bù trừ [3].",
