    "explanation": "Căn cứ: 1. *Giáo trình giao dịch ngoại thương* (PGS.TS Phạm Duy Liên) – Chương IV: Xuất khẩu hàng hóa, Mục 3.3 & Bảng 4.1 \"Cơ cấu giá hàng xuất khẩu theo điều kiện FOB, CFR, CIF\" [1]; Chương II: Incoterms, Mục 2.2.3 \"CFR - Tiền hàng và cước phí\" [2-4]. - 1. **Công thức tính đơn giá CFR (Incoterms 2020):** Theo cơ cấu giá hàng xuất khẩu, đơn giá CFR bao gồm giá bán ban đầu (giá tại xưởng/cơ sở) cộng chi phí vận tải nội địa đưa hàng ra cảng bốc (cảng đi) và cước phí vận tải quốc tế từ cảng bốc đến cảng dỡ (cảng đến) [1, 11]. \\\\[\\text{Đơn giá CFR} = \\text{Giá gốc} + \\text{Chi phí vận tải nội địa (kho } \\rightarrow \\text{ Cát Lái)} + \\text{Cước vận tải quốc tế (Cát Lái } \\rightarrow \\text{ Vancouver)}\\\\] \\\\[\\text{Đơn giá CFR} = 3,000.00\\,\\text{USD/MT} + 10.00\\,\\text{USD/MT} + 150.00\\,\\text{USD/MT} = 3,160.00\\,\\text{USD/MT}\\\\] 2. **Quy tắc ghi địa điểm kèm theo điều kiện CFR (Incoterms 2020):** CFR (Cost and Freight - Tiền hàng và cước phí) là quy tắc thuộc nhóm C dành riêng cho vận tải biển và thủy nội địa [8]. Địa điểm bắt buộc phải ghi kèm theo ba chữ cái \"CFR\" là **Cảng đến quy định (Port of Destination)** [5, 7, 8], tức là **Vancouver Port, Canada** (không phải cảng đi Cát Lái, Việt Nam) [9, 10]. Do đó, cách thể hiện đơn giá chuẩn xác trong hợp đồng thương mại là: **3,160.00 USD/MT CFR Vancouver Port, Canada, Incoterms 2020** [5]. 3. **Phân tích các đáp án khác:** - **A (Sai địa điểm):** Ghi cảng đi *Cat Lai Port, Vietnam* thay vì cảng đến *Vancouver Port, Canada* [5, 10]. - **B (Sai mức giá):** Mới chỉ cộng cước biển (\\\\(3,000 + 150 = 3,150\\\\)), bỏ sót chi phí vận chuyển nội địa ra cảng bốc (\\\\(10\\text{ USD/MT}\\\\)) [1]. - **D (Sai mức giá):** Mới chỉ tính giá FOB Cát Lái (\\\\(3,000 + 10 = 3,010\\\\)), chưa cộng cước vận tải biển quốc tế (\\\\(150\\text{ USD/MT}\\\\)) [1, 12].",
