    "answer": "A",
    "explanation": "Căn cứ: `Giáo trình giao dịch ngoại thương.pdf` (PGS.TS Phạm Duy Liên, NXB Lao Động - Xã Hội) – Chương III: Hợp đồng trong giao dịch thương mại quốc tế – Mục 3.1: Hợp đồng dịch vụ giao nhận [1]. - + **Bản chất học thuật:** Hợp đồng dịch vụ giao nhận (Forwarding Service Contract) là hợp đồng thương mại dịch vụ mà bên nhận ủy thác (Forwarder) đại diện cho bên ủy thác thực hiện các nghiệp vụ giao nhận, làm thủ tục hải quan và vận tải [2]. Trong quá trình tác nghiệp tại cảng, bên nhận ủy thác thường phải chi ứng trước các khoản phụ phí và phí dịch vụ phát sinh thực tế (phí D/O, nâng hạ container, lưu xe, giám định...) [1]. Để đảm bảo quyền lợi tài chính, tính minh bạch và tránh tranh chấp sau khi hoàn thành dịch vụ, Điều khoản Thanh toán trong hợp đồng giao nhận bắt buộc phải quy định cụ thể danh mục các khoản chi phí phát sinh này, đồng thời xác định rõ phương thức thanh toán, đồng tiền tính giá/thanh toán và thời hạn hoàn trả chi phí cho bên nhận ủy thác [1, 3]. + **Trích dẫn chính xác từ tài liệu:** Tại Mục 3.1 (*Hợp đồng dịch vụ giao nhận*), Chương III của *Giáo trình giao dịch ngoại thương.pdf*, nội dung chuẩn mực của Điều khoản Thanh toán được quy định rõ [1]: > *\"Điều 4: Thanh toán* > *Điều khoản này cần làm rõ:* > *- Chi phí: Cước phí vận chuyển, chi phí bốc, dỡ hàng, chi phí lưu xe, chi phí nâng hạ tại cảng, phụ phí xếp dỡ, phí D/O, phí giám định...* > *- Phương thức, đồng tiền, thời gian thanh toán.\"* [1] + Các phương án B, C, D đều sai do vi phạm nguyên tắc quản lý chi phí thực chi thực thanh trong nghiệp vụ ủy thác giao nhận ngoại thương (phương án B gánh ép chi phí sai bản chất đại lý [4], phương án C thiếu căn cứ pháp lý văn bản dễ dẫn đến tranh chấp [5, 6], phương án D làm vô hiệu hóa vai trò ứng phó linh hoạt của Forwarder tại cảng [2]).",
