    "explanation": "Căn cứ: Giáo trình giao dịch ngoại thương.pdf* / Chương III: Hợp đồng trong giao dịch thương mại quốc tế / Mục 2.3: Hợp đồng gia công (Tiểu mục 2.3.6: Vấn đề liên quan đến quyền sở hữu công nghiệp) [1]. - + Trong hoạt động gia công quốc tế, bên đặt gia công có nghĩa vụ bảo đảm tính hợp pháp về quyền sở hữu công nghiệp đối với nhãn hiệu, nhãn mác sản phẩm mà mình giao hoặc chỉ định cho bên nhận gia công sản xuất [1]. Theo Giáo trình Giao dịch thương mại quốc tế (Chương III, Mục 2.3.6), để tránh trường hợp vi phạm quyền sở hữu công nghiệp, trong hợp đồng gia công các bên phải quy định rõ trách nhiệm của bên đặt gia công đối với nhãn mác sản phẩm, bao gồm việc cung cấp giấy chứng nhận quyền sở hữu và đăng ký bản quyền/nhãn hiệu tại nước nhận gia công [1]. + Bên đặt gia công (Công ty X) đã cam kết bằng văn bản về quyền sở hữu hợp pháp đối với nhãn hiệu \"SUN\", nhưng thực tế nhãn hiệu này đã được Công ty Z đăng ký bảo hộ độc quyền trước đó tại Việt Nam. Hành vi này của Công ty X cấu thành vi phạm cam kết hợp đồng và vi phạm nghĩa vụ bảo đảm quyền sở hữu trí tuệ đối với sản phẩm gia công [1, 2]. + Do Công ty Y chỉ thực hiện sản xuất theo đúng chỉ định và trên cơ sở cam kết hợp pháp của bên đặt gia công, nên Công ty Y có quyền yêu cầu Công ty X bồi thường toàn bộ thiệt hại và chi phí xử lý phát sinh do vi phạm của Công ty X gây ra [1, 2].",
